-- Historical entity-derived SQLite fixture from supplied v3 archive. Not an exported Room schema or a production database.
-- Entities.kt SHA256: 2195d007790c7fc23621e53512ffc8520f3405f0cb9e99eb4eae132ef0e9322f
CREATE TABLE `projects` (`id` INTEGER NOT NULL, `name` TEXT NOT NULL, `hfSourceRepo` TEXT NOT NULL, `hfDestRepo` TEXT NOT NULL, `sourceConfig` TEXT NOT NULL, `sourceSplit` TEXT NOT NULL, `imageColumn` TEXT NOT NULL, `idColumn` TEXT NOT NULL, `targetSplit` TEXT NOT NULL, `activeTasksCsv` TEXT NOT NULL, `classesCsv` TEXT NOT NULL, `diskBudgetMb` INTEGER NOT NULL, `modelPath` TEXT, `modelConfigJson` TEXT, `prefetchEnabled` INTEGER NOT NULL, `settingsJson` TEXT NOT NULL DEFAULT '{}', `lastRowCursor` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `batches` (`projectId` INTEGER NOT NULL, `batchNumber` INTEGER NOT NULL, `status` TEXT NOT NULL, `totalCases` INTEGER NOT NULL, `validatedCases` INTEGER NOT NULL, `rejectedCases` INTEGER NOT NULL, `deferredCases` INTEGER NOT NULL, `hfCommitSha` TEXT, `archivePath` TEXT, `archiveSnapshot` TEXT, `verifiedArchiveUri` TEXT, `verifiedArchiveSha256` TEXT, `verificationKind` TEXT, `remotePrefix` TEXT, `remoteBranch` TEXT, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`projectId`,`batchNumber`));
CREATE TABLE `samples` (`sampleId` TEXT NOT NULL, `projectId` INTEGER NOT NULL, `batchNumber` INTEGER NOT NULL, `assetId` TEXT NOT NULL, `sourceRowIndex` INTEGER NOT NULL, `sourceOrdinal` INTEGER, `sourceFileUrl` TEXT, `localImagePath` TEXT, `imageWidth` INTEGER NOT NULL, `imageHeight` INTEGER NOT NULL, `sha256` TEXT, `phash` INTEGER, `sourceSha256` TEXT, `imageTransform` TEXT NOT NULL DEFAULT 'identity', `groupId` TEXT, `split` TEXT NOT NULL, `acquisitionStatus` TEXT NOT NULL, `annotationStatus` TEXT NOT NULL, `syncStatus` TEXT NOT NULL, `auditReason` TEXT, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`sampleId`));
CREATE TABLE `annotations` (`sampleId` TEXT NOT NULL, `dataJson` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`sampleId`));
CREATE TABLE `audit_logs` (`id` INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, `sampleId` TEXT, `batchNumber` INTEGER NOT NULL, `action` TEXT NOT NULL, `details` TEXT NOT NULL, `projectId` INTEGER NOT NULL DEFAULT 1, `timestamp` INTEGER NOT NULL);
CREATE TABLE `source_entries` (`projectId` INTEGER NOT NULL, `ordinal` INTEGER NOT NULL, `assetId` TEXT NOT NULL, `imageRef` TEXT NOT NULL, `sourceRowIndex` INTEGER, `groupId` TEXT, `annotationJson` TEXT, PRIMARY KEY(`projectId`,`ordinal`));
CREATE TABLE `model_profiles` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `modelPath` TEXT NOT NULL, `sha256` TEXT NOT NULL, `configJson` TEXT NOT NULL, `tensorReport` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
